#include <vector>

class Solution {
public:
    int findMinFibonacciNumbers(int k) {
        std::vector<int> fib = {1, 1};
        while (fib.back() < k) {
            int nextFib = fib[fib.size() - 1] + fib[fib.size() - 2];
            fib.push_back(nextFib);
        }
        int count = 0;
        for (int i = (int)fib.size() - 1; i >= 0 && k > 0; --i) {
            if (k >= fib[i]) {
                k -= fib[i];
                count++;
            }
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int findMinFibonacciNumbers(int k) {
        List<Integer> fib = new ArrayList<>(Arrays.asList(1, 1));
        while (fib.get(fib.size() - 1) < k) {
            int nextFib = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
            fib.add(nextFib);
        }
        int count = 0;
        for (int i = fib.size() - 1; i >= 0 && k > 0; i--) {
            int f = fib.get(i);
            if (k >= f) {
                k -= f;
                count++;
            }
        }
        return count;
    }
}

